			rts
if9_e_go:			lea if9_e, sp
			rts
do10_t_go:			lea do10_t, sp
			rts

p_chkl_c:		; call chkl
			movea.l (sp)+, a0		; got
			move.l (a0), var_chkl_got
			movea.l (sp)+, a0		; want
			move.l (a0), var_chkl_want
			move.l sp, p_chkl_rs
			lea p_chkl, sp
			rts
p_chkl_r:		; end of chkl
			movea.l p_chkl_rs, sp
			rts
p_chk_c:		; call chk
			movea.l (sp)+, a0		; got
			move.w (a0), var_chk_got
			movea.l (sp)+, a0		; want
			move.w (a0), var_chk_want
			move.l sp, p_chk_rs
			lea p_chk, sp
			rts
p_chk_r:		; end of chk
			movea.l p_chk_rs, sp
			rts
p_chks_c:		; call chks
			movea.l (sp)+, a0		; got
			lea var_chks_got, a1
			move.w #40, d1
			subq.w #1, d1
			bmi p_chks_si0_e
p_chks_si0:
			move.b (a0)+, (a1)+
			dbeq d1, p_chks_si0
			beq p_chks_si0_z
p_chks_si0_e:
			clr.b (a1)
p_chks_si0_z:
			movea.l (sp)+, a0		; want
			lea var_chks_want, a1
			move.w #40, d1
			subq.w #1, d1
			bmi p_chks_si1_e
p_chks_si1:
			move.b (a0)+, (a1)+
			dbeq d1, p_chks_si1
			beq p_chks_si1_z
p_chks_si1_e:
			clr.b (a1)
p_chks_si1_z:
			move.l sp, p_chks_rs
			lea p_chks, sp
			rts
p_chks_r:		; end of chks
			movea.l p_chks_rs, sp
			rts
p_twice_c:		; call twice
			movea.l (sp)+, a0		; v
			move.l (a0), var_twice_v
			clr.l var_twice_twice
			move.l sp, p_twice_rs
			lea p_twice, sp
			rts
p_twice_r:		; end of twice
			movea.l p_twice_rs, sp
			rts
p_addto_c:		; call addto
			movea.l (sp)+, a0		; x
			move.l a0, p_addto_a0
			move.l (a0), var_addto_x
			movea.l (sp)+, a0		; y
			move.l (a0), var_addto_y
			move.l sp, p_addto_rs
			lea p_addto, sp
			rts
p_addto_r:		; end of addto
			movea.l p_addto_a0, a1
			move.l var_addto_x, (a1)
			movea.l p_addto_rs, sp
			rts
p_fact_c:		; call fact
			movea.l (sp)+, a0		; k
			move.w (a0), var_fact_k
			clr.l var_fact_fact
			clr.l var_fact_r
			move.l sp, p_fact_rs
			lea p_fact, sp
			rts
p_fact_r:		; end of fact
			movea.l p_fact_rs, sp
			rts

